        // CONSTRAINT 1: Exactly-Once Processing Semantics (EOS)
        // Trade-off: Higher latency and throughput overhead due to transactional commits.
        props.put("processing.guarantee", "exactly_once_v2");

        // CONSTRAINT 2: State Store Management (RocksDB)
        // Trade-off: High disk I/O potential vs. memory usage.
        // Cache sizing must be tuned to balance between latency (RAM) and capacity (Disk).
        props.put("default.deserialization.exception.handler", "logAndContinue");

        StreamsBuilder builder = new StreamsBuilder();

        // CONSTRAINT 3: Out-of-Order Data Handling
        // Trade-off: Grace period defines how long we wait for late data.
        // Longer windows increase result completeness but significantly increase latency and state size.
        KStream<String, String> source = builder.stream("input-topic");

        source.groupByKey()
              .windowedBy(TimeWindows.ofSizeWithNoGrace(Duration.ofMinutes(5))
                      .advanceBy(Duration.ofMinutes(1)))
              // Trade-off: Materializing stores allows fault tolerance but consumes disk space.
              .aggregate(() -> 0L, (k, v, agg) -> agg + 1, 
                      Materialized.as("aggregated-store"))
              .toStream()
              .to("output-topic");

        Topology topology = builder.build();

        // CONSTRAINT 4: Threading and Parallelism
        // Trade-off: Increasing threads increases parallelism but adds context-switching overhead.
        // KafkaStreams instances > 1 provides HA but requires coordination.
        KafkaStreams streams = new KafkaStreams(topology, props);

        // CONSTRAINT 5: Consumer Lag / Backpressure
        // If processing time > ingestion rate, lag grows. Must partition effectively or scale horizontally.
        streams.start();

        Runtime.getRuntime().addShutdownHook(new Thread(streams::close));
    }
